const score = parseInt($json.body.score);
const category = score >= 9 ? 'PROMOTER' : score >= 7 ? 'PASSIVE' : 'DETRACTOR';
return [{json: {score, category, comment: $json.body.comment || '', client_id: $json.body.client_id}}];

return $input.all().map(item => {
  const f = item.json.fields;
  const daysSinceLast = f.last_communication ?
    Math.floor((Date.now() - new Date(f.last_communication)) / 86400000) : 30;
  let score = 100;
  if (daysSinceLast > 21) score = 20;
  else if (daysSinceLast > 14) score = 40;
  else if (daysSinceLast > 7) score = 70;
  else if (daysSinceLast > 3) score = 85;
  const flag = (daysSinceLast > 14) ? '🔴 WARN' : '';
  return {json: {...item.json, comm_score: score, days_since_comm: daysSinceLast, comm_flag: flag}};
});

return $input.all().map(item => {
  const f = item.json.fields;
  const reliability = f.payment_reliability || 70;
  let score = reliability;
  const overdue = f.overdue_count || 0;
  if (overdue > 0) score -= overdue * 15;
  score = Math.max(0, Math.min(100, score));
  const flag = (score < 50) ? '🟡 WATCH' : '';
  return {json: {...item.json, payment_score: score, payment_flag: flag}};
});

return $input.all().map(item => {
  const f = item.json.fields;
  const nps = f.satisfaction_score || 7;
  const revisions = f.total_revisions || 0;
  const milestones = f.total_milestones || 1;
  const revRatio = revisions / milestones;
  let score = nps * 10;
  if (revRatio > 3) score -= 20;
  else if (revRatio > 2) score -= 10;
  score = Math.max(0, Math.min(100, score));
  const flag = (revRatio > 3) ? '🟡 HIGH MAINT' : '';
  return {json: {...item.json, satisfaction_score: score, rev_ratio: revRatio, sat_flag: flag}};
});

const items = $input.all();
const avgRate = items.reduce((s,i) => {
  const rev = i.json.fields.lifetime_value || 0;
  const hrs = i.json.fields.total_hours || 1;
  return s + (rev/hrs);
}, 0) / (items.length || 1);
return items.map(item => {
  const f = item.json.fields;
  const rev = f.lifetime_value || 0;
  const hrs = f.total_hours || 1;
  const rate = rev / hrs;
  const score = Math.min(100, Math.round((rate / (avgRate || 1)) * 70));
  const flag = (rate < avgRate * 0.5) ? '🔴 ENERGY VAMPIRE' : '';
  return {json: {...item.json, revenue_score: score, hourly_rate: Math.round(rate), agency_avg_rate: Math.round(avgRate), revenue_flag: flag}};
});

return $input.all().map(item => {
  const j = item.json;
  const health = Math.round(
    (j.comm_score * 0.25) + (j.payment_score * 0.30) +
    (j.satisfaction_score * 0.25) + (j.revenue_score * 0.20)
  );
  let risk = '🟢 Healthy';
  if (health < 40) risk = '🔴 Critical';
  else if (health < 60) risk = '🟠 At Risk';
  else if (health < 80) risk = '🟡 Watch';
  return {json: {...j, health_score: health, risk_level: risk}};
});

return $input.all().map(item => {
  const j = item.json;
  let risk = 0;
  if (j.comm_score < 40) risk += 30;
  if (j.payment_score < 50) risk += 25;
  if (j.satisfaction_score < 50) risk += 25;
  if (j.revenue_score < 30) risk += 20;
  let urgency = 'LOW';
  if (risk > 70) urgency = 'CRITICAL';
  else if (risk > 50) urgency = 'HIGH';
  else if (risk > 30) urgency = 'MEDIUM';
  return {json: {...j, churn_risk: risk, churn_urgency: urgency}};
});

return $input.all().map(item => {
  const j = item.json; const f = j.fields || {};
  const revenue = f.lifetime_value || 0;
  const hours = f.total_hours || 1;
  const cost = hours * 50;
  const revCost = (f.total_revisions || 0) * 75;
  const profit = revenue - cost - revCost;
  const roi = revenue > 0 ? Math.round((profit / revenue) * 100) : 0;
  let cls = '⚠️ Neutral';
  if (roi > 60 && j.health_score > 80) cls = '🌟 Golden Client';
  else if (roi > 40 && j.health_score > 60) cls = '✅ Good Client';
  else if (roi < 20 || (j.health_score < 40 && hours > 20)) cls = '🧹 Energy Vampire';
  return {json: {...j, true_profit: profit, roi_pct: roi, client_class: cls}};
});

const ALL_SERVICES = ['Web Dev','SEO','Ads','Social','Branding','Email Marketing'];
return $input.all().map(item => {
  const j = item.json; const f = j.fields || {};
  const current = (f.services || '').split(',').map(s=>s.trim());
  const missing = ALL_SERVICES.filter(s => !current.includes(s));
  let upsell_flag = '';
  if (missing.length > 0 && j.health_score > 60 && j.roi_pct > 40) {
    upsell_flag = 'UPSELL: ' + missing.slice(0,2).join(', ');
  }
  return {json: {...j, upsell_candidates: missing, upsell_flag: upsell_flag}};
});

