const invs = $('📋 All Invoices').all().map(i=>i.json.fields);
const cls = $('📋 All Clients').all().map(i=>i.json.fields);
const now = new Date();
const thisMonth = invs.filter(i => {
  const d = new Date(i.paid_at || i.sent_at);
  return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
});
const paid = thisMonth.filter(i => i.status === 'Paid');
const outstanding = invs.filter(i => i.status === 'Sent' || i.status === 'Overdue');
const revenue = paid.reduce((s,i) => s + (i.amount || 0), 0);
const outstandingAmt = outstanding.reduce((s,i) => s + (i.amount || 0), 0);
const activeClients = cls.filter(c => c.stage === 'Active').length;
const avgHealth = cls.filter(c=>c.stage==='Active').reduce((s,c) => s + (c.health_score||0), 0) / (activeClients||1);
return [{json: {
  revenue_this_month: revenue, outstanding_amount: outstandingAmt,
  invoices_paid: paid.length, invoices_outstanding: outstanding.length,
  active_clients: activeClients, avg_health: Math.round(avgHealth),
  total_clients: cls.length
}}];

